package references

// newQuestItemReferences owns player-facing quest metadata.
func newQuestItemReferences() map[QuestItem]InventoryItem {
	return map[QuestItem]InventoryItem{
		Amulet:           {ItemName: "Amulet", ItemDisplayName: "Amulet of Lord British", ItemPickupMessage: "The Amulet of Lord British!", ItemSprite: 439, ItemDescription: "The magical amulet consists of a silver, serpentine medallion suspended from a gold chain, its likeness variously attributed to Britannia's rarely-observed silver serpents, and even the Great Earth Serpent itself. It emanates a blue aura and is notably warm to the touch, imbued with enchantments that have allowed it both to facilitate interplanetary moongate travel and pierce supernatural forms of darkness.", ItemDescriptionAttribution: "UltimaCodex.com"},
		Crown:            {ItemName: "Crown", ItemDisplayName: "Crown of Lord British", ItemPickupMessage: "The Crown of Lord British!", ItemSprite: 437, ItemDescription: "Lord British's Crown is one of Lord British's Royal Crown Jewels. It has a powerful magic effect that the Avatar will need to discover!", ItemDescriptionAttribution: "UltimaCodex.com and The Book of Brad"},
		Sceptre:          {ItemName: "Sceptre", ItemDisplayName: "Sceptre of Lord British", ItemPickupMessage: "The Sceptre of Lord British!", ItemSprite: 438, ItemDescription: "The Sceptre of Lord British, one of the three Royal Crown Jewels, is a powerful magical artifact. This powerful tool has an amazing ability that the Avatar will need to discover!", ItemDescriptionAttribution: "UltimaCodex.com and The Book of Brad"},
		ShardOfFalsehood: {ItemName: "ShardOfFalsehood", ItemDisplayName: "Shard of Falsehood", ItemPickupMessage: "The Shard of Falsehood!", ItemSprite: 436, ItemDescription: "At the same time as Lord British was gaining a reputation for fair and honest government over his provinces and attracting attention for his startlingly innovative ideas, Mondain was using his father's gem against itself to produce a black jewel that would render him and his evil immortal. Success meant gaining even greater power over the minions of darkness.\n\nWithin days, a stranger arrived in Sosaria. With utter devotion to truth and good, the stranger grew into a hero capable of facing Mondain. Eventually, the heroic stranger found the malevolent gem and destroyed it, along with its creator. With Mondain's destruction, the forces of evil began to wane.\n\nThis shard is one third of that very powerful gem!", ItemDescriptionAttribution: "The Book of Lore (Ultima V)"},
		ShardOfHatred:    {ItemName: "ShardOfHatred", ItemDisplayName: "Shard of Hatred", ItemPickupMessage: "The Shard of Hatred!", ItemSprite: 436, ItemDescription: "At the same time as Lord British was gaining a reputation for fair and honest government over his provinces and attracting attention for his startlingly innovative ideas, Mondain was using his father's gem against itself to produce a black jewel that would render him and his evil immortal. Success meant gaining even greater power over the minions of darkness.\n\nWithin days, a stranger arrived in Sosaria. With utter devotion to truth and good, the stranger grew into a hero capable of facing Mondain. Eventually, the heroic stranger found the malevolent gem and destroyed it, along with its creator. With Mondain's destruction, the forces of evil began to wane.\n\nThis shard is one third of that very powerful gem!", ItemDescriptionAttribution: "The Book of Lore (Ultima V)"},
		ShardOfCowardice: {ItemName: "ShardOfCowardice", ItemDisplayName: "Shard of Cowardice", ItemPickupMessage: "The Shard of Cowardice!", ItemSprite: 436, ItemDescription: "At the same time as Lord British was gaining a reputation for fair and honest government over his provinces and attracting attention for his startlingly innovative ideas, Mondain was using his father's gem against itself to produce a black jewel that would render him and his evil immortal. Success meant gaining even greater power over the minions of darkness.\n\nWithin days, a stranger arrived in Sosaria. With utter devotion to truth and good, the stranger grew into a hero capable of facing Mondain. Eventually, the heroic stranger found the malevolent gem and destroyed it, along with its creator. With Mondain's destruction, the forces of evil began to wane.\n\nThis shard is one third of that very powerful gem!", ItemDescriptionAttribution: "The Book of Lore (Ultima V)"},
		Carpet:           {ItemName: "Carpet", ItemDisplayName: "Magic Carpet", ItemPickupMessage: "A Magic Carpet!", ItemSprite: 283, ItemDescription: "Said to have been brought to Britannia from a faraway land of trackless deserts and strange, humped beasts, the magic carpet is an excellent conveyance for quick travel over swamps, calm waters and other places when ground travel is impeded or imperiled. Since it flies only a handspan from the ground, it cannot be used to pass over mountains, walls, or any sort of high obstruction. Rapid waters will soak it, subjecting its riders to freezing spray and possible drowning.", ItemDescriptionAttribution: "Paths of Destiny (Ultima V)"},
		Grapple:          {ItemName: "Grapple", ItemDisplayName: "Grapple", ItemPickupMessage: "A Grappling Hook!", ItemSprite: 12, ItemDescription: "The grapple is an important tool for mountain-climbing.", ItemDescriptionAttribution: "UltimaCodex.com"},
		Spyglass:         {ItemName: "Spyglass", ItemDisplayName: "Spyglass", ItemPickupMessage: "A Spyglass!", ItemSprite: 89, ItemDescription: "Normally used by sailors as a navigational aid, it is possible to study the planets and brighter stars with even a small spyglass. ", ItemDescriptionAttribution: "Paths of Destiny (Ultima V)"},
		HMSCape:          {ItemName: "HMSCape", ItemDisplayName: "H.M.S. Cape Plans", ItemPickupMessage: "Plans for the H.M.S. Cape!", ItemSprite: 260, ItemDescription: "The H.M.S. Cape had seen better days. Algae and ribbons of seaweed covered her. Bloated, dead sailors bobbed with the current, arms and legs tangled in the seaweed and wreckage. I shuddered at the sight of their watery grave, but I did not hesitate.", ItemDescriptionAttribution: "Ultima: The Avatar Adventures"},
		PocketWatch:      {ItemName: "PocketWatch", ItemDisplayName: "Pocket Watch", ItemPickupMessage: "A Pocket Watch!", ItemSprite: 256, ItemDescription: "A pocket watch is a portable timepiece meant to be kept in one's pocket. Such a device numbers among the scant personal affects that the Avatar brought to Britannia from Earth, and the hero routinely carries this particular pocket watch. ", ItemDescriptionAttribution: "UltimaCodex.com"},
		BlackBadge:       {ItemName: "BlackBadge", ItemDisplayName: "Black Badge", ItemPickupMessage: "A Black Badge!", ItemSprite: 256, ItemDescription: "Exploring the dark paths of Blackthorn's palace may be quite hazardous to the health of one who is not recognizable as a member of the Oppression.", ItemDescriptionAttribution: "Paths of Destiny (Ultima V)"},
		WoodenBox:        {ItemName: "WoodenBox", ItemDisplayName: "Sandalwood Box", ItemPickupMessage: "A sandalwood box!", ItemSprite: 270, ItemDescription: "What a curious little box... You feel compelled to bring it along on your journey.", ItemDescriptionAttribution: "The Book of Brad"},
		Sextant:          {ItemName: "Sextant", ItemDisplayName: "Sextant", ItemPickupMessage: "A Sextant!", ItemSprite: 256, ItemDescription: "The sextant is a tool commonly used in celestial navigation, as it allows its user to take an accurate measurement of a heavenly body relative to the horizon. Once a navigator ascertains this angle, he may use it to reliably determine his geographic position. ", ItemDescriptionAttribution: "UltimaCodex.com"},
	}
}
